+    }
+    return load(backend);
+  }
+
+  /** The one scenario the runner selected from {@code backend}'s contract. */
+  public static Operation selectedScenario(String backend) {
+    return selectedScenario(backend, System.getenv(SCENARIO_INDEX_VARIABLE));
+  }
